namespace StockManager.Report
{
    public partial class frmBaoCaoThucHien : FormBase, IForm
    {
        public const string PERMISSION_VIEW = "frmBaoCaoThucHien_View";
        public const string PERMISSION_EDIT = "frmBaoCaoThucHien_Edit";

        DataTable dtbMonthList = null;
        DataTable dtbData = null;
        private bool bolIsRefresh = false;

        #region IForm Members

        private static frmBaoCaoThucHien _instance = null;

        public static frmBaoCaoThucHien Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmBaoCaoThucHien();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmBaoCaoThucHien()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {

        }

        private void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                AccountObject.ACC_Receipt obj = new AccountObject.ACC_Receipt();
                dtbData = obj.GetDataTable("ACC_Receipt_BaoCaoThucHienTheoKhachHang",
                        "@FromDate", dtmFrom.EditValueDate,
                        "@ToDate", dtmTo.EditValueDate);
                if (dtbData != null)
                {
                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, "ACC_Receipt_BaoCaoThucHienTheoKhachHang", bolIsRefresh);
                    ModifyGrid();
                    mnuItemExportExcel.Enabled = true;
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        private void ModifyGrid()
        {
            foreach (DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn col in gvData.Columns)
            {
                if (col.FieldName.Contains("DoanhThu_"))
                    col.AppearanceCell.BackColor = Color.LightBlue;
                else if (col.FieldName == "TongDoanhThu")
                    col.AppearanceCell.BackColor = Color.YellowGreen;
            }

            #region Định dạng lưới

            SMS_OutputType obj = new SMS_OutputType();
            dtbMonthList = obj.GetDataTable("SMS_MonthList",
                       "@FromDate", dtmFrom.EditValueDate,
                       "@ToDate", dtmTo.EditValueDate);

            if (dtbMonthList != null)
            {
                if (dtbMonthList.Rows.Count > 12)
                {
                    MessageManager.Warning("Hệ thống chỉ hỗ trợ thống kê thời gian 12 tháng!");
                    dtmTo.Focus();
                    return;
                }

                for (int i = 1; i <= dtbMonthList.Rows.Count; i++)
                {
                    if (gvData.Columns["DoanhThu_" + i].OwnerBand != null)
                    {
                        gvData.Columns["DoanhThu_" + i].OwnerBand.Caption = "THÁNG " + Convert.ToDateTime(dtbMonthList.Rows[i - 1]["Month"]).ToString("MM/yy");
                        gvData.Columns["DoanhThu_" + i].OwnerBand.Visible = true;
                    }
                }

                for (int i = dtbMonthList.Rows.Count + 1; i <= 12; i++)
                {
                    if (gvData.Columns["DoanhThu_" + i].OwnerBand != null)
                        gvData.Columns["DoanhThu_" + i].OwnerBand.Visible = false;
                }
            }

            #endregion
        }

        #endregion

        #region Form Actions

        static bool bolIsLoaded = false;
        private void frmBaoCaoThucHien_Load(object sender, EventArgs e)
        {
            if (!bolIsLoaded)
            {
                DateTime dtm = DateTime.Now;
                dtmFrom.EditValue = new DateTime(dtm.Year, 1, 1);
                dtmTo.EditValue = new DateTime(dtm.Year, 12, 31);

                SetToolTip();
                CheckPermission();
                bolIsLoaded = true;
            }
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void frmBaoCaoThucHien_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;

                case Keys.Escape:
                    btnClose_Click(sender, null);
                    break;
            }
        }

        #endregion

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            btnSearch_Click(null, null);
        }

        private void mnuItemExportExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (dtmFrom.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày bắt đầu!");
                dtmFrom.Focus();
                return;
            }
            if (dtmTo.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày kết thúc!");
                dtmTo.Focus();
                return;
            }

            string strSummary = "TongDoanhThu";
            for (int i = 1; i <= 12; i++)
                strSummary += ",DoanhThu_" + i.ToString();

            gvData.SummaryCollection = strSummary;

            new Thread(LoadData).Start();
        }
    }
}

