using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Text;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using System.Threading;
using Libs;
using Global;
using SMSObject;

namespace StockManager.Report
{
    public partial class frmBaoCaoThucHien : FormBase, IForm
    {
        public const string PERMISSION_VIEW = "frmBaoCaoThucHien_View";
        public const string PERMISSION_EDIT = "frmBaoCaoThucHien_Edit";

        DataTable dtbMonthList = null;
        DataTable dtbData = null;
        private bool bolIsRefresh = false;
        private string strStore_Prev = "";

        #region IForm Members

        private static frmBaoCaoThucHien _instance = null;

        public static frmBaoCaoThucHien Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmBaoCaoThucHien();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmBaoCaoThucHien()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            uOffice.OfficeFilter = UserSession.GetOfficeFilter(PERMISSION_VIEW);
        }

        private void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                if (bolIsRefresh)
                    uOffice.RefrehData();
                else
                    uOffice.InitData();
            }
        }

        private string GetStoreName()
        {
            if (rdoShowType1.Checked)
                return "SMS_OutputVoucher_BaoCaoKhoiLuongThucHienTheoKhachHang";
            return "ACC_Receipt_BaoCaoThucHienTheoKhachHang";
        }

        private string GetGridQueryName()
        {
            if (rdoShowType1.Checked)
                return "SMS_OutputVoucher_BaoCaoKhoiLuongThucHienTheoKhachHang";
            return "ACC_Receipt_BaoCaoThucHienTheoKhachHang";
        }

        private string GetMonthFieldPrefix()
        {
            if (rdoShowType1.Checked)
                return "KhoiLuong_";
            return "DoanhThu_";
        }

        private string GetTotalFieldName()
        {
            if (rdoShowType1.Checked)
                return "TongKhoiLuong";
            return "TongDoanhThu";
        }

        private void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                string strStore = GetStoreName();
                if (strStore != strStore_Prev)
                {
                    strStore_Prev = strStore;
                    bolIsRefresh = true;
                }

                dtbData = null;
                if (rdoShowType1.Checked)
                {
                    SMS_OutputVoucher obj = new SMS_OutputVoucher();
                    dtbData = obj.GetDataTable(strStore,
                            "@OfficeID", uOffice.EditValue,
                            "@FromDate", dtmFrom.EditValueDate,
                            "@ToDate", dtmTo.EditValueDate);
                }
                else
                {
                    AccountObject.ACC_Receipt obj = new AccountObject.ACC_Receipt();
                    dtbData = obj.GetDataTable(strStore,
                            "@OfficeID", uOffice.EditValue,
                            "@FromDate", dtmFrom.EditValueDate,
                            "@ToDate", dtmTo.EditValueDate);
                }

