using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Text;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using System.Threading;
using Libs;
using Global;
using SMSObject;

namespace StockManager.Report
{
    public partial class frmBaoCaoThucHienV2 : FormBase, IForm
    {
        public const string PERMISSION_VIEW = "frmBaoCaoThucHienV2_View";
        public const string PERMISSION_EDIT = "frmBaoCaoThucHienV2_Edit";
        private const string STORE_NAME = "BaoCaoThucHien_TongHop";
        private const string GRID_QUERY_NAME = "BaoCaoThucHien_TongHop";

        DataTable dtbMonthList = null;
        DataTable dtbData = null;
        private bool bolIsRefresh = false;

        #region IForm Members

        private static frmBaoCaoThucHienV2 _instance = null;

        public static frmBaoCaoThucHienV2 Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmBaoCaoThucHienV2();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmBaoCaoThucHienV2()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            uOffice.OfficeFilter = UserSession.GetOfficeFilter(PERMISSION_VIEW);
        }

        private void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                if (bolIsRefresh)
                    uOffice.RefrehData();
                else
                    uOffice.InitData();
            }
        }

        private void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                dtbData = null;
                SMS_OutputVoucher obj = new SMS_OutputVoucher();
                dtbData = obj.GetDataTable(STORE_NAME,
                        "@OfficeID", uOffice.EditValue,
                        "@FromDate", dtmFrom.EditValueDate,
                        "@ToDate", dtmTo.EditValueDate);

                if (dtbData != null)
                {
                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, GRID_QUERY_NAME, bolIsRefresh);
                    ModifyGrid();
                    mnuItemExportExcel.Enabled = true;
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        private void SetupGroupGrid()
        {
            gvData.BeginSort();
            try
            {
                foreach (DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn col in gvData.Columns)
                {
                    if (col.FieldName == "LoaiBaoCaoOrder" || col.FieldName == "RowOrderIndex")
                        col.Visible = false;

                    if (col.FieldName == "LoaiBaoCao")
                    {
                        col.GroupIndex = 0;
                        col.Visible = false;
                    }

                    if (col.FieldName == "TongGiaTri")
                    {
                        col.AppearanceCell.BackColor = Color.LightBlue;
                        col.AppearanceCell.Font = new Font(col.AppearanceCell.Font, FontStyle.Bold);
                    }
                }

                gvData.OptionsView.ShowGroupPanel = false;
                gvData.OptionsView.ShowGroupedColumns = false;
                gvData.OptionsView.GroupFooterShowMode = DevExpress.XtraGrid.Views.Grid.GroupFooterShowMode.VisibleIfExpanded;

                gvData.GroupSummary.Clear();
                for (int i = 1; i <= 12; i++)
                {
                    DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn colMonth = gvData.Columns["GiaTri_" + i.ToString()];
                    if (colMonth != null && colMonth.Visible)
                    {
                        gvData.GroupSummary.Add(DevExpress.Data.SummaryItemType.Sum, colMonth.FieldName, colMonth, "{0:#,##0}");
                    }
                }

                DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn colTotal = gvData.Columns["TongGiaTri"];
                if (colTotal != null)
                {
                    gvData.GroupSummary.Add(DevExpress.Data.SummaryItemType.Sum, colTotal.FieldName, colTotal, "{0:#,##0}");
                }

                gvData.ExpandAllGroups();
            }
            finally
            {
                gvData.EndSort();
            }
        }

        private void ModifyGrid()
        {
            SetupGroupGrid();

            #region Định dạng lưới

            SMS_OutputType obj = new SMS_OutputType();
            dtbMonthList = obj.GetDataTable("SMS_MonthList",
                       "@FromDate", dtmFrom.EditValueDate,
                       "@ToDate", dtmTo.EditValueDate);

            if (dtbMonthList != null)
            {
                if (dtbMonthList.Rows.Count > 12)
                {
                    MessageManager.Warning("Hệ thống chỉ hỗ trợ thống kê thời gian 12 tháng!");
                    dtmTo.Focus();
                    return;
                }

                for (int i = 1; i <= dtbMonthList.Rows.Count; i++)
                {
                    DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn col = gvData.Columns["GiaTri_" + i.ToString()];
                    if (col != null)
                    {
                        col.Caption = Convert.ToDateTime(dtbMonthList.Rows[i - 1]["Month"]).ToString("MM/yyyy");
                        col.Visible = true;
                    }
                }

                for (int i = dtbMonthList.Rows.Count + 1; i <= 12; i++)
                {
                    DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn col = gvData.Columns["GiaTri_" + i.ToString()];
                    if (col != null)
                        col.Visible = false;
                }

                SetupGroupGrid();
            }

            #endregion
        }

        #endregion

        #region Form Actions

        static bool bolIsLoaded = false;
        private void frmBaoCaoThucHienV2_Load(object sender, EventArgs e)
        {
            if (!bolIsLoaded)
            {
                DateTime dtm = DateTime.Now;
                dtmFrom.EditValue = new DateTime(dtm.Year, 1, 1);
                dtmTo.EditValue = new DateTime(dtm.Year, 12, 31);

                SetToolTip();
                CheckPermission();
                new Thread(LoadReferenceData).Start();
                bolIsLoaded = true;
            }
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void frmBaoCaoThucHienV2_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;

                case Keys.Escape:
                    btnClose_Click(sender, null);
                    break;
            }
        }

        private void gvData_CustomDrawGroupRow(object sender, DevExpress.XtraGrid.Views.Base.RowObjectCustomDrawEventArgs e)
        {
            DevExpress.XtraGrid.Views.Grid.ViewInfo.GridGroupRowInfo info = e.Info as DevExpress.XtraGrid.Views.Grid.ViewInfo.GridGroupRowInfo;
            if (info == null)
                return;

            DevExpress.XtraGrid.Views.Grid.GridView view = sender as DevExpress.XtraGrid.Views.Grid.GridView;
            if (view == null)
                return;

            int intCount = view.GetChildRowCount(e.RowHandle);
            info.GroupText = string.Format("{0} ({1} dòng)", info.GroupValueText, intCount);
        }

