        {
            bolIsRefresh = true;
            btnSearch_Click(null, null);
        }

        private void mnuItemExportExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (dtmFrom.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày bắt đầu!");
                dtmFrom.Focus();
                return;
            }
            if (dtmTo.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày kết thúc!");
                dtmTo.Focus();
                return;
            }

            gvData.SummaryCollection = "";

            new Thread(LoadData).Start();
        }
    }
}

