private void ModifyGrid()
{
    #region Định dạng lưới

    SMS_OutputType obj = new SMS_OutputType();
    dtbMonthList = obj.GetDataTable("SMS_MonthList",
               "@FromDate", dtmFrom.EditValueDate,
               "@ToDate", dtmTo.EditValueDate);

    if (dtbMonthList != null)
    {
        if (dtbMonthList.Rows.Count > 12)
        {
            MessageManager.Warning("Hệ thống chỉ hỗ trợ thống kê thời gian 12 tháng!");
            dtmTo.Focus();
            return;
        }

        for (int i = 1; i <= dtbMonthList.Rows.Count; i++)
        {
            DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn col = gvData.Columns["GiaTri_" + i.ToString()];
            if (col != null)
            {
                col.Caption = Convert.ToDateTime(dtbMonthList.Rows[i - 1]["Month"]).ToString("MM/yyyy");
                col.Visible = true;
            }
        }

        for (int i = dtbMonthList.Rows.Count + 1; i <= 12; i++)
        {
            DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn col = gvData.Columns["GiaTri_" + i.ToString()];
            if (col != null)
                col.Visible = false;
        }
    }

    #endregion

    SetupGroupGrid();
}

