private void SetupGroupGrid()
{
    gvData.BeginUpdate();
    gvData.BeginSort();
    try
    {
        gvData.ClearGrouping();

        foreach (DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn col in gvData.Columns)
        {
            if (col.FieldName == "LoaiBaoCaoOrder" || col.FieldName == "RowOrderIndex")
                col.Visible = false;

            if (col.FieldName == "TongGiaTri")
            {
                col.AppearanceCell.BackColor = Color.LightBlue;
                col.AppearanceCell.Font = new Font(col.AppearanceCell.Font, FontStyle.Bold);
            }
        }

        DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn colGroup = gvData.Columns.ColumnByFieldName("LoaiBaoCao") as DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn;
        if (colGroup != null)
        {
            colGroup.GroupIndex = 0;
            colGroup.Visible = false;
        }

        gvData.GroupSummary.Clear();
        for (int i = 1; i <= 12; i++)
        {
            DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn colMonth = gvData.Columns.ColumnByFieldName("GiaTri_" + i.ToString()) as DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn;
            if (colMonth != null && colMonth.Visible)
            {
                gvData.GroupSummary.Add(DevExpress.Data.SummaryItemType.Sum, colMonth.FieldName, colMonth, "{0:#,##0}");
            }
        }

        DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn colTotal = gvData.Columns.ColumnByFieldName("TongGiaTri") as DevExpress.XtraGrid.Views.BandedGrid.BandedGridColumn;
        if (colTotal != null)
        {
            gvData.GroupSummary.Add(DevExpress.Data.SummaryItemType.Sum, colTotal.FieldName, colTotal, "{0:#,##0}");
        }

        gvData.ExpandAllGroups();
    }
    finally
    {
        gvData.EndSort();
        gvData.EndUpdate();
    }
}

