                    "@ScienceIDOfTeacher", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupIDOfTeacher", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                     "@TeacherTypeID", lookupTeacherTypeID.EditValueInt32,
                      "@chkNOTlaiXe", chkNOTlaiXe.Checked,
                    "@Semester", "2"
                );

                // Gộp và tính tổng theo giáo viên
                dtbData = MergeAndSumByTeacher(dtbHK1, dtbHK2);
            }
            else
            {
                dtbData = obj.GetDataTable(
                    "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
                    "@ScienceIDOfTeacher", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupIDOfTeacher", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                     "@TeacherTypeID", lookupTeacherTypeID.EditValueInt32,
                     "@chkNOTlaiXe", chkNOTlaiXe.Checked,
                    "@Semester", uYearSemester.SemesterEditValue
                );
            }

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                gcData.DataSource = null;
                MessageManager.Warning("Không có dữ liệu!");
                return;
            }

            // Thêm các cột tính toán tổng hợp
            AddComputedColumns();

            // Sắp xếp theo đơn vị (khoa) rồi tên GV để nhóm gọn
            if (dtbData.Columns.Contains("ScienceName"))
                dtbData.DefaultView.Sort = "ScienceName ASC, TeacherLastName ASC, TeacherFirstName ASC";

            InitGrid();
            gcData.DataSource = dtbData;
            gvData.BestFitColumns();

            if (chkHasTeachingHours.Checked)
                dtbData.DefaultView.RowFilter = "TongLTTH > 0";

            gvData.ExpandAllGroups();
        }

        private void InitGrid()
        {
            gvData.Bands.Clear();
            gvData.Columns.Clear();
            gvData.SummaryCollection = "";

            if (dtbData == null || dtbData.Columns.Count == 0)
                return;

            // Không cho sửa trực tiếp trên lưới
            gvData.OptionsBehavior.Editable = false;

            // Band: GIẢNG VIÊN
            GridBand gbTeacher = CreateBand("GIẢNG VIÊN");

            // Band: GIỜ CHUẨN / KIÊM NHIỆM
            GridBand gbStandard = CreateBand("GIỜ CHUẨN / KIÊM NHIỆM");

            // Band: COI THI / CHẤM THI / SOẠN ĐỀ
            GridBand gbExam = CreateBand("COI THI / CHẤM THI / SOẠN ĐỀ");

            // Band: CV HỌC TẬP / HOẠT ĐỘNG KHÁC
            GridBand gbCV = CreateBand("CV HỌC TẬP / HOẠT ĐỘNG KHÁC");

            // Band: NCKH
            GridBand gbNCKH = CreateBand("NCKH");

            // Band: GIẢNG DẠY THỰC TẾ
            GridBand gbTeaching = CreateBand("GIẢNG DẠY THỰC TẾ");

            // Band: TỔNG HỢP
            GridBand gbSummary = CreateBand("TỔNG HỢP");

            // Duyệt từng cột trong DataTable và phân vào band phù hợp
            foreach (DataColumn dc in dtbData.Columns)
            {
                string colName = dc.ColumnName;
                string caption = GetVietnameseCaption(colName);
                int width = GetDefaultWidth(colName);
                string format = GetDefaultFormat(colName);
                DevExpress.Utils.HorzAlignment align = GetDefaultAlignment(colName);

                GridBand targetBand = GetBandForColumn(colName,
                    gbTeacher, gbExam, gbStandard, gbCV, gbNCKH, gbTeaching, gbSummary);

                if (targetBand == null)
                {
                    // Cột không được phân vào band, tạo band mặc định
                    targetBand = gbTeaching;
                }

                BandedGridColumn col = new BandedGridColumn();
                col.FieldName = colName;
                col.Caption = caption;
                col.Name = "gcol" + colName;
                col.Visible = !IsTemporaryHiddenColumn(colName);
                col.Width = width;

                col.AppearanceHeader.Options.UseTextOptions = true;
                col.AppearanceHeader.TextOptions.HAlignment =
                    DevExpress.Utils.HorzAlignment.Center;
                col.AppearanceHeader.TextOptions.WordWrap =
                    DevExpress.Utils.WordWrap.Wrap;

                col.AppearanceCell.Options.UseTextOptions = true;
                col.AppearanceCell.TextOptions.HAlignment = align;

                if (!string.IsNullOrEmpty(format))
                {
                    col.DisplayFormat.FormatString = format;
                    col.DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
                }

                gvData.Columns.Add(col);
                targetBand.Columns.Add(col);

                // Highlight các cột tính toán
                HighlightColumnIfNeeded(colName, col);
            }

            ApplySummaryColumnOrder(gbSummary);

            // Tổng hợp SummaryCollection cho các cột số
            BuildSummaryCollection();

            // Tăng chiều cao header band để hiển thị text xuống dòng
            gvData.BandPanelRowHeight = 40;

            // Phân cấp theo khoa (đơn vị): dòng nhóm xanh + danh sách GV bên dưới
            ApplyScienceGrouping();
        }

        /// <summary>
        /// Nhóm lưới theo ScienceName (Đơn vị/Khoa):
        /// dòng nhóm màu xanh = tên khoa, bên dưới là giáo viên thuộc khoa đó.
        /// </summary>
        private void ApplyScienceGrouping()
        {
            BandedGridColumn colScience = gvData.Columns.ColumnByFieldName("ScienceName") as BandedGridColumn;
            if (colScience == null)
                return;

            // Style dòng nhóm khoa
            gvData.Appearance.GroupRow.BackColor = Color.FromArgb(146, 208, 80);
            gvData.Appearance.GroupRow.ForeColor = Color.FromArgb(0, 70, 0);
            gvData.Appearance.GroupRow.Font = new Font("Tahoma", 9, FontStyle.Bold);
            gvData.Appearance.GroupRow.Options.UseBackColor = true;
            gvData.Appearance.GroupRow.Options.UseForeColor = true;
            gvData.Appearance.GroupRow.Options.UseFont = true;

            gvData.OptionsView.ShowGroupedColumns = false;
            gvData.OptionsView.ShowGroupPanel = false;
            gvData.GroupFormat = "[#image]{1} ({2} GV)";

            colScience.GroupIndex = 0;
            colScience.SortOrder = DevExpress.Data.ColumnSortOrder.Ascending;

            // Vẽ lại chữ dòng nhóm cho rõ (tên khoa)
            gvData.CustomDrawGroupRow -= gvData_CustomDrawGroupRow;
            gvData.CustomDrawGroupRow += gvData_CustomDrawGroupRow;
        }

        private void gvData_CustomDrawGroupRow(object sender, DevExpress.XtraGrid.Views.Base.RowObjectCustomDrawEventArgs e)
        {
            DevExpress.XtraGrid.Views.Grid.ViewInfo.GridGroupRowInfo info =
                e.Info as DevExpress.XtraGrid.Views.Grid.ViewInfo.GridGroupRowInfo;
            if (info == null)
                return;

            object objValue = gvData.GetGroupRowValue(e.RowHandle);
            string strScienceName = (objValue == null || objValue == DBNull.Value)
                ? "(Chưa có đơn vị)"
                : objValue.ToString();

            if (string.IsNullOrEmpty(strScienceName))
                strScienceName = "(Chưa có đơn vị)";

            int intChildCount = gvData.GetChildRowCount(e.RowHandle);
            info.GroupText = String.Format("{0}  ({1} GV)", strScienceName, intChildCount);
        }

        private void ApplySummaryColumnOrder(GridBand gbSummary)
        {
            string[] summaryOrder = {
                "TongSoGioGiangDayHoatDong",
                "DinhMucTong2024",
                "VuotToiThieu"
            };

            List<BandedGridColumn> orderedColumns = new List<BandedGridColumn>();
            foreach (string colName in summaryOrder)
            {
                BandedGridColumn col = gvData.Columns.ColumnByFieldName(colName) as BandedGridColumn;
                if (col != null && col.OwnerBand == gbSummary)
                    orderedColumns.Add(col);
            }

            if (orderedColumns.Count == 0)
                return;

            gbSummary.Columns.Clear();
            foreach (BandedGridColumn col in orderedColumns)
                gbSummary.Columns.Add(col);
        }

        private GridBand CreateBand(string caption)
        {
            GridBand band = new GridBand();
            band.Caption = caption;
            band.AppearanceHeader.Font = new Font("Tahoma", 8, FontStyle.Bold);
            band.AppearanceHeader.Options.UseFont = true;
            band.AppearanceHeader.TextOptions.HAlignment = DevExpress.Utils.HorzAlignment.Center;
            band.AppearanceHeader.Options.UseTextOptions = true;
            gvData.Bands.Add(band);
            return band;
        }

        private bool IsTemporaryHiddenColumn(string colName)
        {
            // Tạm ẩn: Số giờ coi thi, Số bài chấm thi, LT, TH, TeacherTypeID, Đơn vị (ScienceName — vẫn dùng để nhóm khoa)
            return colName == "SoGio_CoiThi"
                || colName == "SoBai_ChamThi"
                || colName == "TotalQuantity_Theory"
                || colName == "TotalQuantity_Practice"
                || colName == "TeacherTypeID"
                || colName == "ScienceName";
        }

        private GridBand GetBandForColumn(string colName,
            GridBand gbTeacher, GridBand gbExam, GridBand gbStandard,
            GridBand gbCV, GridBand gbNCKH, GridBand gbTeaching, GridBand gbSummary)
        {
            string upper = colName.ToUpper();

            // GIẢNG VIÊN
            if (upper.Contains("TEACHERID")
                || upper.Contains("TEACHERTYPEID")
                || upper.Contains("TEACHERFIRSTNAME")
                || upper.Contains("TEACHERLASTNAME")
                || upper.Contains("TEACHERNAME")
                || colName == "TeacherName"
                || colName == "ScienceID"
                || colName == "ScienceName")
                return gbTeacher;

            // COI THI / CHẤM THI / SOẠN ĐỀ
            if (upper.Contains("COITHI")
                || upper.Contains("CHAMTHI")
                || upper.Contains("GIOQUYDOI_COITHI")
                || upper.Contains("GIOQUYDOI_CHAMTHI")
                || upper.Contains("SOGIO_COITHI")
                || upper.Contains("SOBAI_CHAMTHI")
                || colName == "SoGioSoanDe"
                || colName == "TongCoiThiChamThiSoanDe")
                return gbExam;

            // TỔNG HỢP (phải kiểm tra trước GIỜ CHUẨN để tránh DinhMucTong2024 bị bắt nhầm)
            if (colName == "TongSoGioGiangDayHoatDong"
                || colName == "DinhMucTong2024"
                || colName == "VuotToiThieu")
                return gbSummary;

            // GIỜ CHUẨN / KIÊM NHIỆM
            if (upper.Contains("STANDARDQUANTITY")
                || upper.Contains("RATIOPOSITION")
                || upper.Contains("REALSTANDARDQUANTITY")
                || upper.Contains("DINHMUC"))
                return gbStandard;

            // CV HỌC TẬP / HOẠT ĐỘNG KHÁC
            if (upper.Contains("W34")
                || upper.Contains("W35")
                || upper.Contains("HOCTAP")
                || upper.Contains("BOIDUONG")
                || upper.Contains("HOATDONG"))
                return gbCV;

            // NCKH
            if (upper.Contains("NCKH")
                || upper.Contains("RESEARCH"))
                return gbNCKH;

            // GIẢNG DẠY THỰC TẾ (mặc định)
            return gbTeaching;
        }

