            if (upper.Contains("TONGSOGIOGIANGDAYHOATDONG"))
            {
                col.AppearanceCell.BackColor = Color.FromArgb(198, 224, 180);
                col.AppearanceCell.Options.UseBackColor = true;
                col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
                col.AppearanceCell.Options.UseFont = true;
            }

            // Highlight Định mức tổng 2024
            if (upper.Contains("DINHMUCTONG"))
            {
                col.AppearanceCell.BackColor = Color.FromArgb(221, 235, 247);
                col.AppearanceCell.Options.UseBackColor = true;
                col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
