            }

            // Highlight Vượt tối thiểu
            if (upper.Contains("VUOTTOITHIEU"))
            {
                col.AppearanceCell.BackColor = Color.FromArgb(255, 192, 192);
                col.AppearanceCell.Options.UseBackColor = true;
                col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
                col.AppearanceCell.Options.UseFont = true;
            }

            // Highlight Tổng CT+CT+SD
            if (upper.Contains("TONGCOITHICHAMTHIS"))
            {
                col.AppearanceCell.BackColor = Color.FromArgb(255, 235, 156);
                col.AppearanceCell.Options.UseBackColor = true;
                col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
                col.AppearanceCell.Options.UseFont = true;
            }

            // Highlight Quy đổi giờ
            if (upper.Contains("QUYDOIGIO") && !upper.Contains("COITHI") && !upper.Contains("CHAMTHI"))
            {
                col.AppearanceCell.BackColor = Color.LightSkyBlue;
                col.AppearanceCell.Options.UseBackColor = true;
                col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
                col.AppearanceCell.Options.UseFont = true;
            }
        }

        private void BuildSummaryCollection()
        {
            System.Text.StringBuilder sb = new System.Text.StringBuilder();

            foreach (DataColumn dc in dtbData.Columns)
            {
                string upper = dc.ColumnName.ToUpper();

                // Chỉ tính tổng cho các cột số
                if (dc.DataType == typeof(decimal)
                    || dc.DataType == typeof(double)
                    || dc.DataType == typeof(int)
                    || dc.DataType == typeof(long)
                    || dc.DataType == typeof(float))
                {
                    // Bỏ qua TeacherID / TeacherTypeID và các cột ID
                    if (upper == "TEACHERID" || upper == "TEACHERTYPEID")
                        continue;

                    if (sb.Length > 0)
                        sb.Append(",");
                    sb.Append(dc.ColumnName);
                }
            }

            gvData.SummaryCollection = sb.ToString();
        }

        private void AddComputedColumns()
        {
            // Kiểm tra các cột nguồn tồn tại
            string[] requiredCols = {
                "StandardQuantity_DinhMucGiangDay",
                "TeacherTypeID",
                "TotalFinal_W34_HocTapBoiDuong",
                "TotalFinal_W35_HoatDongKhac",
                "ResearchNow_NCKH",
                "TongLTTH",
                "GioQuyDoi_CoiThi",
                "GioQuyDoi_ChamThi",
                "SoGioSoanDe"
            };

            foreach (string col in requiredCols)
            {
                if (!dtbData.Columns.Contains(col))
                    return;
            }

            // Tổng coi thi + chấm thi + soạn đề
            // = Giờ QĐ coi thi + Giờ QĐ chấm thi + Giờ soạn đề
            if (!dtbData.Columns.Contains("TongCoiThiChamThiSoanDe"))
            {
                dtbData.Columns.Add("TongCoiThiChamThiSoanDe", typeof(decimal),
                    "ISNULL(GioQuyDoi_CoiThi, 0) + ISNULL(GioQuyDoi_ChamThi, 0) + ISNULL(SoGioSoanDe, 0)");
            }

            // Tổng số giờ giảng dạy, hoạt động
            // = Tổng CT+CT+SD + HT bồi dưỡng + HĐ khác + NCKH + Tổng LT+TH
            if (!dtbData.Columns.Contains("TongSoGioGiangDayHoatDong"))
            {
                dtbData.Columns.Add("TongSoGioGiangDayHoatDong", typeof(decimal),
                    "ISNULL(TongCoiThiChamThiSoanDe, 0) + ISNULL(TotalFinal_W34_HocTapBoiDuong, 0) + ISNULL(TotalFinal_W35_HoatDongKhac, 0) + ISNULL(ResearchNow_NCKH, 0) + ISNULL(TongLTTH, 0)");
            }

            // Tổng định mức giờ chuẩn (sau cột Tổng số giờ giảng dạy, hoạt động)
            // TeacherTypeID = 5 (GV khoa): ĐM GD + 26 (HTBD) + 78 (NCKH) + 52 (HĐ khác) — số cứng định mức
            // TeacherTypeID = 8 (GV khoa trung tâm): ĐM GD + 78 (NCKH)
            if (!dtbData.Columns.Contains("DinhMucTong2024"))
            {
                string dinhMucExpr = String.Format(
                    "IIF(ISNULL(TeacherTypeID, 0) = 5, ISNULL(RealStandardQuantity_DinhMucGiangDayNamHoc, 0) + {0} + {1} + {2}, IIF(ISNULL(TeacherTypeID, 0) = 8, ISNULL(RealStandardQuantity_DinhMucGiangDayNamHoc, 0) + {1}, 0))",
                    THRESHOLD_HOCTAP_BOIDUONG,
                    THRESHOLD_NCKH,
                    THRESHOLD_HOATDONG_KHAC);

                dtbData.Columns.Add("DinhMucTong2024", typeof(decimal), dinhMucExpr);
            }

            // Vượt tối thiểu = Tổng số giờ giảng dạy, hoạt động - Tổng định mức giờ chuẩn
            if (!dtbData.Columns.Contains("VuotToiThieu"))
            {
                dtbData.Columns.Add("VuotToiThieu", typeof(decimal),
                    "ISNULL(TongSoGioGiangDayHoatDong, 0) - ISNULL(DinhMucTong2024, 0)");
            }
        }

