        private DataTable MergeAndSumByTeacher(DataTable dtbHK1, DataTable dtbHK2)
        {
            if (dtbHK1 == null || dtbHK1.Rows.Count == 0)
                return dtbHK2;

            if (dtbHK2 == null || dtbHK2.Rows.Count == 0)
                return dtbHK1;

            // Clone cấu trúc từ bảng HK1
            DataTable dtbResult = dtbHK1.Clone();

            // Lấy danh sách các cột số cần tính tổng
            List<string> listNumericCols = new List<string>();

            foreach (DataColumn col in dtbResult.Columns)
            {
                if (col.DataType == typeof(decimal)
                    || col.DataType == typeof(double)
                    || col.DataType == typeof(int)
                    || col.DataType == typeof(long)
                    || col.DataType == typeof(float))
                {
                    // Không cộng TeacherID / TeacherTypeID khi gộp cả năm
                    if (col.ColumnName != "TeacherID"
                        && col.ColumnName != "TeacherTypeID")
                        listNumericCols.Add(col.ColumnName);
                }
            }

            // Dictionary để lookup nhanh theo TeacherID
            Dictionary<string, DataRow> dictData = new Dictionary<string, DataRow>();

            // Xử lý bảng HK1
            foreach (DataRow row in dtbHK1.Rows)
            {
                string strTeacherID = row["TeacherID"].ToString();
                DataRow newRow = dtbResult.NewRow();

                foreach (DataColumn col in dtbResult.Columns)
                {
                    newRow[col.ColumnName] = row[col.ColumnName];
                }

                dictData[strTeacherID] = newRow;
            }

            // Xử lý bảng HK2 - cộng dồn các cột số
            foreach (DataRow row in dtbHK2.Rows)
            {
                string strTeacherID = row["TeacherID"].ToString();

                if (dictData.ContainsKey(strTeacherID))
                {
                    DataRow existingRow = dictData[strTeacherID];

                    foreach (string strCol in listNumericCols)
                    {
                        decimal val1 = 0;
                        decimal val2 = 0;

                        if (existingRow[strCol] != DBNull.Value)
                            val1 = Convert.ToDecimal(existingRow[strCol]);

                        if (row[strCol] != DBNull.Value)
                            val2 = Convert.ToDecimal(row[strCol]);

                        existingRow[strCol] = val1 + val2;
                    }
                }
                else
                {
                    DataRow newRow = dtbResult.NewRow();

                    foreach (DataColumn col in dtbResult.Columns)
                    {
                        newRow[col.ColumnName] = row[col.ColumnName];
                    }

                    dictData[strTeacherID] = newRow;
                }
            }

            // Thêm tất cả dòng vào kết quả và áp dụng ngưỡng sau khi cộng 2 kỳ
            foreach (DataRow row in dictData.Values)
            {
                CapCombinedValues(row);
                dtbResult.Rows.Add(row);
            }

            return dtbResult;
        }

        /// <summary>
        /// Áp dụng ngưỡng (cap) sau khi cộng 2 học kỳ (Cả năm)
        /// Vì SQL đã cap theo từng kỳ, cộng lại có thể vượt ngưỡng năm
        /// </summary>
        private void CapCombinedValues(DataRow row)
        {
            string strScienceID = "";
            if (row.Table.Columns.Contains("ScienceID")
                && row["ScienceID"] != DBNull.Value)
            {
                strScienceID = row["ScienceID"].ToString();
            }

            bool bolIsDTLX = (strScienceID == "DTLX");

            // HT, bồi dưỡng: tất cả khoa cap 26
            CapColumn(row, "TotalFinal_W34_HocTapBoiDuong", THRESHOLD_HOCTAP_BOIDUONG);

            // HĐ khác: <> DTLX cap 52, = DTLX cap 26
            CapColumn(row, "TotalFinal_W35_HoatDongKhac",
                bolIsDTLX ? THRESHOLD_HOATDONG_KHAC_DTLX : THRESHOLD_HOATDONG_KHAC);

            // NCKH: <> DTLX cap 78, = DTLX không giới hạn
            if (!bolIsDTLX)
                CapColumn(row, "ResearchNow_NCKH", THRESHOLD_NCKH);
        }

        private void CapColumn(DataRow row, string strColName, decimal dMax)
        {
            if (!row.Table.Columns.Contains(strColName))
                return;

            object objVal = row[strColName];
            if (objVal == DBNull.Value || objVal == null)
                return;

            decimal dVal;
            if (!decimal.TryParse(objVal.ToString(), out dVal))
                return;

            if (dVal > dMax)
                row[strColName] = dMax;
        }

