using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Text;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using DevExpress.XtraGrid.Views.BandedGrid;
using DevExpress.XtraGrid.Views.Grid.ViewInfo;
using System.Threading;
using Libs;
using Global;
using SMSObject;

namespace StockManager.Report
{
    public partial class frmBaoCaoThucHienV2 : FormBase, IForm
    {
        public const string PERMISSION_VIEW = "frmBaoCaoThucHienV2_View";
        public const string PERMISSION_EDIT = "frmBaoCaoThucHienV2_Edit";
        private const string STORE_NAME = "BaoCaoThucHien_TongHop";
        private const string GRID_QUERY_NAME = "BaoCaoThucHien_TongHop";

        DataTable dtbMonthList = null;
        DataTable dtbData = null;
        private bool bolIsRefresh = false;

        #region IForm Members

        private static frmBaoCaoThucHienV2 _instance = null;

        public static frmBaoCaoThucHienV2 Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmBaoCaoThucHienV2();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmBaoCaoThucHienV2()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            uOffice.OfficeFilter = UserSession.GetOfficeFilter(PERMISSION_VIEW);
        }

        private void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                if (bolIsRefresh)
                    uOffice.RefrehData();
                else
                    uOffice.InitData();
            }
        }

        private void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                dtbData = null;
                SMS_OutputVoucher obj = new SMS_OutputVoucher();
                dtbData = obj.GetDataTable(STORE_NAME,
                        "@OfficeID", uOffice.EditValue,
                        "@FromDate", dtmFrom.EditValueDate,
                        "@ToDate", dtmTo.EditValueDate);

                if (dtbData != null)
                {
                    if (dtbData.Rows.Count == 0)
                    {
                        gcData.DataSource = null;
                        MessageManager.Warning("Không có dữ liệu!");
                        bolIsRefresh = false;
                        return;
                    }

                    // Giống frmBangTinhGioDayGiangVien_ALL: cấu hình lưới trước, sort rồi mới bind
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, GRID_QUERY_NAME, bolIsRefresh);

                    if (dtbData.Columns.Contains("LoaiBaoCaoOrder"))
                        dtbData.DefaultView.Sort = "LoaiBaoCaoOrder ASC, RowOrderIndex ASC, Ten ASC";

                    gcData.DataSource = dtbData;
                    ModifyGrid();
                    ApplyLoaiBaoCaoGrouping();
                    gvData.ExpandAllGroups();

                    mnuItemExportExcel.Enabled = true;
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        /// <summary>
        /// Nhóm lưới theo LoaiBaoCao - pattern frmBangTinhGioDayGiangVien_ALL.ApplyScienceGrouping
        /// </summary>
        private void ApplyLoaiBaoCaoGrouping()
        {
            BandedGridColumn colGroup = gvData.Columns.ColumnByFieldName("LoaiBaoCao") as BandedGridColumn;
            if (colGroup == null)
                return;

            gvData.Appearance.GroupRow.BackColor = Color.FromArgb(146, 208, 80);
            gvData.Appearance.GroupRow.ForeColor = Color.FromArgb(0, 70, 0);
            gvData.Appearance.GroupRow.Font = new Font("Tahoma", 9, FontStyle.Bold);
            gvData.Appearance.GroupRow.Options.UseBackColor = true;
            gvData.Appearance.GroupRow.Options.UseForeColor = true;
            gvData.Appearance.GroupRow.Options.UseFont = true;

            gvData.OptionsView.ShowGroupedColumns = false;
            gvData.OptionsView.ShowGroupPanel = false;
            gvData.GroupFormat = "[#image]{1} ({2} dòng)";

            gvData.ClearGrouping();
            colGroup.GroupIndex = 0;
            colGroup.SortOrder = DevExpress.Data.ColumnSortOrder.Ascending;
            colGroup.Visible = false;

            BandedGridColumn colOrder = gvData.Columns.ColumnByFieldName("LoaiBaoCaoOrder") as BandedGridColumn;
            if (colOrder != null)
                colOrder.Visible = false;

            BandedGridColumn colRowOrder = gvData.Columns.ColumnByFieldName("RowOrderIndex") as BandedGridColumn;
            if (colRowOrder != null)
                colRowOrder.Visible = false;

            BandedGridColumn colTotal = gvData.Columns.ColumnByFieldName("TongGiaTri") as BandedGridColumn;
            if (colTotal != null)
            {
                colTotal.AppearanceCell.BackColor = Color.LightBlue;
                colTotal.AppearanceCell.Font = new Font(colTotal.AppearanceCell.Font, FontStyle.Bold);
            }

            gvData.GroupSummary.Clear();
            for (int i = 1; i <= 12; i++)
            {
                BandedGridColumn colMonth = gvData.Columns.ColumnByFieldName("GiaTri_" + i.ToString()) as BandedGridColumn;
                if (colMonth != null && colMonth.Visible)
                {
                    gvData.GroupSummary.Add(DevExpress.Data.SummaryItemType.Sum, colMonth.FieldName, colMonth, "{0:#,##0}");
                }
            }

            if (colTotal != null)
            {
                gvData.GroupSummary.Add(DevExpress.Data.SummaryItemType.Sum, colTotal.FieldName, colTotal, "{0:#,##0}");
            }

            gvData.CustomDrawGroupRow -= gvData_CustomDrawGroupRow;
            gvData.CustomDrawGroupRow += gvData_CustomDrawGroupRow;
        }

        private void ModifyGrid()
        {
            SMS_OutputType obj = new SMS_OutputType();
            dtbMonthList = obj.GetDataTable("SMS_MonthList",
                       "@FromDate", dtmFrom.EditValueDate,
                       "@ToDate", dtmTo.EditValueDate);

            if (dtbMonthList != null)
            {
                if (dtbMonthList.Rows.Count > 12)
                {
                    MessageManager.Warning("Hệ thống chỉ hỗ trợ thống kê thời gian 12 tháng!");
                    dtmTo.Focus();
                    return;
                }

                for (int i = 1; i <= dtbMonthList.Rows.Count; i++)
                {
                    BandedGridColumn col = gvData.Columns.ColumnByFieldName("GiaTri_" + i.ToString()) as BandedGridColumn;
                    if (col != null)
                    {
                        col.Caption = Convert.ToDateTime(dtbMonthList.Rows[i - 1]["Month"]).ToString("MM/yyyy");
                        col.Visible = true;
                    }
                }

                for (int i = dtbMonthList.Rows.Count + 1; i <= 12; i++)
                {
                    BandedGridColumn col = gvData.Columns.ColumnByFieldName("GiaTri_" + i.ToString()) as BandedGridColumn;
                    if (col != null)
                        col.Visible = false;
                }
            }
        }

        #endregion

        #region Form Actions

        static bool bolIsLoaded = false;
        private void frmBaoCaoThucHienV2_Load(object sender, EventArgs e)
        {
            if (!bolIsLoaded)
            {
                DateTime dtm = DateTime.Now;
                dtmFrom.EditValue = new DateTime(dtm.Year, 1, 1);
                dtmTo.EditValue = new DateTime(dtm.Year, 12, 31);

                SetToolTip();
                CheckPermission();
                new Thread(LoadReferenceData).Start();
                bolIsLoaded = true;
            }
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void frmBaoCaoThucHienV2_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;

                case Keys.Escape:
                    btnClose_Click(sender, null);
                    break;
            }
        }

        private void gvData_CustomDrawGroupRow(object sender, DevExpress.XtraGrid.Views.Base.RowObjectCustomDrawEventArgs e)
        {
            GridGroupRowInfo info = e.Info as GridGroupRowInfo;
            if (info == null)
                return;

            object objValue = gvData.GetGroupRowValue(e.RowHandle);
            string strLoaiBaoCao = (objValue == null || objValue == DBNull.Value)
                ? "(Chưa phân loại)"
                : objValue.ToString();

            if (string.IsNullOrEmpty(strLoaiBaoCao))
                strLoaiBaoCao = "(Chưa phân loại)";

            int intChildCount = gvData.GetChildRowCount(e.RowHandle);
            info.GroupText = String.Format("{0}  ({1} dòng)", strLoaiBaoCao, intChildCount);
        }

        #endregion

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            btnSearch_Click(null, null);
        }

        private void mnuItemExportExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (dtmFrom.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày bắt đầu!");
                dtmFrom.Focus();
                return;
            }
            if (dtmTo.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày kết thúc!");
                dtmTo.Focus();
                return;
            }

            gvData.SummaryCollection = "";

            new Thread(LoadData).Start();
        }
    }
}

